    if n <= 1:
        return False
    # Every composite n <= 250 has a divisor d with 2 <= d and d*d <= n.
    # Since 16*16 = 256 > 250, checking d in 2..15 is enough.
    for d in range(2, 16):
        if d * d <= n and n % d == 0:
            return False
    return True


def post(n, result):
    return result == _is_prime_spec(n)
